import numpy as np, wfdb, scipy.signal as sig, json, sys, os

FS=500
LEADS=['I','II','III','aVR','aVF','aVL','V1','V2','V3','V4','V5','V6']

def load(ecg):
    r=wfdb.rdrecord('/tmp/ecgs/%s'%ecg)
    x=np.array(r.p_signal,dtype=float)
    # fill nans
    for i in range(x.shape[1]):
        col=x[:,i]
        m=np.isnan(col)
        if m.all(): col[:]=0
        elif m.any(): col[m]=np.interp(np.flatnonzero(m),np.flatnonzero(~m),col[~m])
    names=list(r.sig_name)
    d={n:x[:,i] for i,n in enumerate(names)}
    return d

def bp(x,lo=0.5,hi=40):
    b,a=sig.butter(3,[lo/(FS/2),hi/(FS/2)],btype='band')
    return sig.filtfilt(b,a,x)

def baseline(x):
    # remove baseline wander with median filters
    w1=int(0.2*FS)|1; w2=int(0.6*FS)|1
    y=sig.medfilt(sig.medfilt(x,w1),w2)
    return x-y

def notch(x):
    for f0 in (60,):
        b,a=sig.iirnotch(f0/(FS/2),30)
        x=sig.filtfilt(b,a,x)
    return x

def detect_r(d):
    # composite: sum of squared derivative across leads
    leads=['II','V1','V5','I','aVF','V2','V3','V4','V6','III','aVL','aVR']
    comp=np.zeros(len(d['I']))
    for L in leads:
        if L in d:
            y=bp(baseline(d[L]),1,30)
            comp+=np.abs(np.gradient(y))**2
    comp=sig.savgol_filter(comp,int(0.05*FS)|1,2)
    comp=comp/ (np.max(comp)+1e-12)
    # adaptive threshold peak finding
    th=np.percentile(comp,98)*0.3
    pk,_=sig.find_peaks(comp,height=th,distance=int(0.22*FS))
    if len(pk)<3: 
        pk,_=sig.find_peaks(comp,height=np.percentile(comp,95)*0.2,distance=int(0.2*FS))
    return pk,comp

def refine_r(d,pk):
    # refine to max |QRS| on composite of abs signals
    y=np.zeros(len(d['I']))
    for L in ['II','V2','V5','I','V1','V3','V4','V6','aVF']:
        if L in d: y+=np.abs(bp(baseline(d[L]),1,40))
    out=[]
    w=int(0.05*FS)
    for p in pk:
        a=max(0,p-w); b=min(len(y),p+w)
        out.append(a+int(np.argmax(y[a:b])))
    return np.array(sorted(set(out)))

def median_beat(d,rpk,pre=0.35,post=0.55):
    a=int(pre*FS); b=int(post*FS)
    segs={L:[] for L in d}
    used=0
    for p in rpk:
        if p-a<0 or p+b>=len(d['I']): continue
        used+=1
        for L in d:
            segs[L].append(baseline(d[L])[p-a:p+b])
    if used<1: return None,None,a
    mb={}
    for L in segs:
        arr=np.array(segs[L])
        mb[L]=np.median(arr,axis=0)
    return mb,used,a
