warnings.filterwarnings('ignore')
sys.path.insert(0,'/tmp/an')
from ecganalyze import load, baseline, FS, LEADS
import neurokit2 as nk
IND=['I','II','V1','V2','V3','V4','V5','V6']
def lp(x,hz=40):
    b,a=sig.butter(4,hz/(FS/2),btype='low'); return sig.filtfilt(b,a,x)
def bp(x,lo=10,hi=45):
    b,a=sig.butter(3,[lo/(FS/2),hi/(FS/2)],btype='band'); return sig.filtfilt(b,a,x)

def rpeaks(dd):
    cands=[]
    for L in ['II','V2','V5','I','V1','V4']:
        try:
            _,info=nk.ecg_peaks(dd[L],sampling_rate=FS,method='neurokit')
            p=np.array(info['ECG_R_Peaks'])
            if len(p)>=4: cands.append((L,p))
        except Exception: pass
    if not cands: return np.array([])
    cands.sort(key=lambda z:len(z[1]))
    L,p=cands[len(cands)//2]
    y=np.zeros(len(dd['I']))
    for LL in IND: y+=np.abs(lp(dd[LL],40))
    w=int(0.04*FS); out=[]
    for q in p:
        a=max(0,q-w); b=min(len(y),q+w)
        out.append(a+int(np.argmax(y[a:b])))
    return np.array(sorted(set(out)))

def analyze(ecg):
    d=load(ecg); dd={L:baseline(d[L]) for L in d}
    rpk=rpeaks(dd); rr=np.diff(rpk)/FS*1000.0
    RRm=float(np.median(rr)) if len(rr) else 800.0
    o={'ecg':ecg,'nbeats':int(len(rpk)),'rr':[round(float(x),1) for x in rr],'RR':RRm,
       'rate':60000.0/RRm,'cv':float(np.std(rr)/np.mean(rr)) if len(rr) else 0,
       'rmssd':float(np.sqrt(np.mean(np.diff(rr)**2))) if len(rr)>1 else 0.0,
       'pnn50':float(np.mean(np.abs(np.diff(rr))>50)) if len(rr)>1 else 0.0,
       'irr':float(np.median(np.abs(np.diff(rr)))/RRm) if len(rr)>1 else 0.0}
    pre=min(0.42,0.46*RRm/1000); post=min(0.62,0.62*RRm/1000)
    a=int(pre*FS); b=int(post*FS)
    segs={L:[] for L in dd}
    for p in rpk:
        if p-a<0 or p+b>=len(dd['I']): continue
        for L in dd: segs[L].append(dd[L][p-a:p+b])
    nb=len(segs['I'])
    if nb<2: o['err']='few'; return o
    mb={L:np.median(np.array(segs[L]),axis=0) for L in dd}
    mbf={L:lp(mb[L],40) for L in mb}
    n=len(mbf['I'])
    # QRS via high-freq envelope
    env=np.zeros(n)
    for L in IND: env+=np.abs(np.gradient(bp(mb[L])))
    env=sig.savgol_filter(env,int(0.016*FS)|1,2)
    R=a-int(0.04*FS)+int(np.argmax(env[a-int(0.04*FS):a+int(0.04*FS)]))
    ep=env[R]; efl=np.percentile(env,20)
    th=efl+0.10*(ep-efl)
    i=R
    while i>max(1,R-int(0.12*FS)) and env[i]>th: i-=1
    qon=i
    j=R
    while j<min(n-2,R+int(0.16*FS)) and env[j]>th: j+=1
    qoff=j
    o['qrs_ms']=(qoff-qon)*2
    vm=np.sqrt(sum(mbf[L]**2 for L in IND))
    b0={L:float(np.median(mbf[L][max(0,qon-int(0.03*FS)):qon+1])) for L in mb}
    # T wave
    tse=min(n-2, qon+int(min(0.66*RRm/1000,0.56)*FS)); s=qoff+int(0.03*FS); tend=None
    if tse>s+10:
        tp=s+int(np.argmax(vm[s:tse]))
        best=None
        for L in ['V2','V3','V4','V5','II','V6','I','V1','aVF','aVL','III']:
            y=lp(mb[L],20); amp=abs(y[tp]-b0[L])
            if best is None or amp>best[0]: best=(amp,L,y)
        amp,L,y=best; bb=b0[L]
        pol=1.0 if y[tp]>bb else -1.0
        dy=np.gradient(y); k1=tp+int(0.015*FS); k2=min(n-2,tp+int(0.28*FS))
        if k2<=k1+2: k2=min(n-2,k1+3)
        m=k1+int(np.argmin(dy[k1:k2]*pol)); sl=dy[m]
        tend=int(m+int((bb-y[m])/sl)) if abs(sl)>1e-9 else k2
        tend=int(max(tp+5,min(n-1,tend)))
        o['tlead']=L;o['tamp']=float(amp);o['qt_ms']=(tend-qon)*2
        o['qtc_ms']=o['qt_ms']/np.sqrt(RRm/1000.0);o['tp']=int(tp);o['tend']=tend
    # P wave on best single lead
    ps=max(0,qon-int(0.26*FS))
    if tend is not None:
        pt=int(tend-RRm/1000*FS)
        if pt>ps: ps=min(pt, qon-int(0.05*FS))
    pe=qon-int(0.006*FS)
    if pe>ps+8:
        best=None
        for L in ['II','aVF','V1','I','III','aVL','V2']:
            y=lp(mb[L],25)-b0[L]
            k=ps+int(np.argmax(np.abs(y[ps:pe])))
            amp=abs(y[k])
            if best is None or amp>best[0]: best=(amp,L,y,k)
        pamp,PL,y,ppk=best
        noise=float(np.std(np.diff(lp(mb[PL],25)[max(0,qon-int(0.05*FS)):qon])))*3+1e-4
        thp=max(0.18*pamp, 0.02)
        i=ppk
        while i>ps and abs(y[i])>thp: i-=1
        pon=i
        jj=ppk
        while jj<pe-1 and abs(y[jj])>thp: jj+=1
        o['p_lead']=PL; o['p_amp']=float(y[ppk]); o['ppk_ms']=(ppk-qon)*2
        o['p_dur_ms']=(jj-pon)*2; o['pr_ms']=(qon-pon)*2; o['pon_ms']=(pon-qon)*2
        o['pamp_II']=float(lp(mb['II'],25)[ppk]-b0['II'])
        # consistency
        cors=[]
        w0,w1=max(0,ppk-int(0.06*FS)),min(n-1,ppk+int(0.06*FS))
        ref=lp(mb[PL],25)[w0:w1]; ref=ref-ref.mean()
        for k in range(nb):
            yy=lp(segs[PL][k],25)[w0:w1]; yy=yy-yy.mean()
            if np.std(yy)>1e-9 and np.std(ref)>1e-9: cors.append(float(np.corrcoef(yy,ref)[0,1]))
        o['p_corr']=float(np.median(cors)) if cors else 0.0
        # count atrial deflections in TQ window (flutter test)
        if tend is not None and (qon-tend)>int(0.06*FS):
            seg=lp(mb[PL],25)[tend:qon]-b0[PL]
            pk1,_=sig.find_peaks(np.abs(seg),height=max(0.4*pamp,0.03),distance=int(0.06*FS))
            o['tq_defl']=int(len(pk1)); o['tq_ms']=(qon-tend)*2
    def net(L):
        y=mbf[L][qon:qoff+1]-b0[L]; return float(y.max()+y.min())
    def ar(L):
        return float(np.sum(mbf[L][qon:qoff+1]-b0[L]))
    o['axis_net']=float(np.degrees(np.arctan2(net('aVF'),net('I'))))
    o['axis_area']=float(np.degrees(np.arctan2(ar('aVF'),ar('I'))))
    o['nets']={L:round(net(L),2) for L in LEADS}
    o['qon']=int(qon);o['qoff']=int(qoff);o['R']=int(R);o['a']=int(a)
    feat={}
    for L in LEADS:
        y=mbf[L][qon:qoff+1]-b0[L]
        feat[L]={'max':round(float(y.max()),2),'imax':int(np.argmax(y))*2,'min':round(float(y.min()),2),'imin':int(np.argmin(y))*2,'end':round(float(y[-1]),2)}
    o['feat']=feat
    np.save('/tmp/an/mb_%s.npy'%ecg,np.array([mbf[L]-b0[L] for L in LEADS]))
    return o
if __name__=='__main__':
    import glob
    res={}
    for f in sorted(glob.glob('/tmp/ecgs/*.hea')):
        e=f.split('/')[-1][:-4]
        try: res[e]=analyze(e)
        except Exception as ex:
            import traceback; traceback.print_exc(); res[e]={'ecg':e,'error':repr(ex)}
    json.dump(res,open('/tmp/an/m5.json','w'),indent=1)
    for e,r in sorted(res.items()):
        print('%s n=%2d rate=%5.1f cv=%.2f rmssd=%5.1f irr=%.2f | qrs=%3.0f pr=%3.0f pdur=%3.0f pl=%-3s pamp=%+.2f pII=%+.2f pcorr=%+.2f tq=%s/%s | qt=%3.0f qtc=%3.0f | axis %5.0f/%5.0f'%(
          e,r.get('nbeats',0),r.get('rate',0),r.get('cv',0),r.get('rmssd',0),r.get('irr',0),r.get('qrs_ms',0),r.get('pr_ms',0),r.get('p_dur_ms',0),
          r.get('p_lead'),r.get('p_amp',0),r.get('pamp_II',0),r.get('p_corr',0),r.get('tq_defl'),r.get('tq_ms'),r.get('qt_ms',0),r.get('qtc_ms',0),r.get('axis_net',0),r.get('axis_area',0)))
